def make_comparator(numeric, unique=False):
    def compare(a, b):
        ka, kb = a[1], b[1]
        if numeric:
            va, vb = numval(ka), numval(kb)
            c = (va > vb) - (va < vb)
        else:
            c = (ka > kb) - (ka < kb)
        if c:
            return c
        if unique:
            # GNU sort drops the last-resort whole-line comparison under
            # -u; stable sorting then preserves input order among ties.
            return 0
        la, lb = a[0], b[0]  # last resort: whole line
        return (la > lb) - (la < lb)
    return compare

